{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE snitch_db.maplemonk.demand_supply_actual AS ( with demand_long_pre as ( select category as l1_category, case when l1_category = \'T-shirts\' then \'T-Shirts\' else l1_category end as category, print_design, fit, collar, \"01-06-2025\", \"01-07-2025\", \"01-08-2025\", \"01-01-2026\", \"01-09-2025\", \"01-10-2025\", \"01-11-2025\", \"01-12-2025\", \"01-02-2026\", \"01-03-2026\" from snitch_db.maplemonk.DEMAND_DATA_20250725 ), demand_long AS ( SELECT a.category, a.l1_category, fit, collar, print_design, TO_DATE(month_str, \'DD-MM-YYYY\') AS month, TRY_CAST(REPLACE(demand_str, \',\', \'\') AS INTEGER) AS demand_qty FROM demand_long_pre a UNPIVOT ( demand_str FOR month_str IN ( \"01-06-2025\",\"01-07-2025\",\"01-08-2025\", \"01-09-2025\",\"01-10-2025\",\"01-11-2025\",\"01-12-2025\",\"01-02-2026\",\"01-01-2026\", \"01-03-2026\")) ), supply_plan_conversion_noos AS ( SELECT a.sku_group, b.category AS category, \'noos\' as product_category, month, b.fit, b.collar, b.print_design, CASE WHEN LOWER(a.sku_group) LIKE \'4mbg%\' THEN \'plus_size\' WHEN LOWER(b.style) LIKE \'%luxe%\' THEN \'luxe\' WHEN LOWER(b.style) LIKE \'%core%\' THEN \'core\' WHEN LOWER(b.category) IN (\'perfumes\',\'accessories\',\'bags\',\'belts\',\'sunglasses\',\'shoes\',\'slip-ons\') THEN \'long_tail\' ELSE \'Snitch\' END AS l1_category, SUM(supply_qty) AS supply_qty from (select SUBSTRING(a.sku, 2) AS sku_group, case when DATE_TRUNC(\'month\',TO_DATE(REPLACE(a.expected_delivery_date, \'-\', \'/\'),\'DD/MM/YYYY\')) = \'0025-09-01\' then \'2025-09-01\' else DATE_TRUNC(\'month\',TO_DATE(REPLACE(a.expected_delivery_date, \'-\', \'/\'),\'DD/MM/YYYY\')) end AS month, SUM(a.proj_qty) AS supply_qty from snitch_db.maplemonk.prod_demand_noos a group by 1,2 ) a LEFT JOIN snitch_db.maplemonk.metafields_data b ON lower(a.sku_group) = lower(b.sku_group) WHERE b.category IS NOT NULL GROUP BY 1,2,3,4,5,6,7,8 ), supply_plan_conversion_repeat AS ( SELECT a.sku_group, b.category AS category, \'repeat\' as product_category, month, b.fit, b.collar, b.print_design, CASE WHEN LOWER(a.sku_group) LIKE \'4mbg%\' THEN \'plus_size\' WHEN LOWER(b.style) LIKE \'%luxe%\' THEN \'luxe\' WHEN LOWER(b.style) LIKE \'%core%\' THEN \'core\' WHEN LOWER(b.category) IN (\'perfumes\',\'accessories\',\'bags\',\'belts\',\'sunglasses\',\'shoes\',\'slip-ons\') THEN \'long_tail\' ELSE \'Snitch\' END AS l1_category, SUM(supply_qty) AS supply_qty from (select SUBSTRING(a.sku, 2) AS sku_group, DATE_TRUNC(\'month\',TO_DATE(REPLACE(a.\"EXPECTED_DELIVERY_DATE \", \'-\', \'/\'),\'DD/MM/YYYY\')) AS month, SUM(a.proj_qty) AS supply_qty FROM snitch_db.maplemonk.prod_demand_repeat a group by 1,2 )a LEFT JOIN snitch_db.maplemonk.metafields_data b ON lower(a.sku_group) = lower(b.sku_group) WHERE b.category IS NOT NULL GROUP BY 1,2,3,4,5,6,7,8 ), supply_plan_fob AS ( SELECT sku AS sku_group, CASE WHEN category = \'Shorts\' THEN \'Shorts\' WHEN category = \'Jacket\' THEN \'Jackets\' WHEN category = \'T-SHIRT\' THEN \'T-Shirts\' WHEN category = \'Sweater\' THEN \'Sweatshirts\' WHEN category IN (\'Oversized shirt\',\'SHIRT\') THEN \'Shirts\' WHEN category = \'TROUSER\' THEN \'Trousers\' WHEN category = \'Trackpants\' THEN \'Jogger & Trackpants\' WHEN category = \'CARGO\' THEN \'Cargo Pants\' WHEN category = \'DENIM\' THEN \'Jeans\' ELSE category END AS category, \'fob\' as product_category, case when DATE_TRUNC(\'month\',TO_DATE(REPLACE(expected_delivery_date, \'-\', \'/\'),\'DD/MM/YYYY\')) = \'0202-08-01\' then \'2025-08-01\' else DATE_TRUNC(\'month\',TO_DATE(REPLACE(expected_delivery_date, \'-\', \'/\'),\'DD/MM/YYYY\')) end as month, fit, collar, print_design, CASE WHEN LOWER(sku) LIKE \'4mbg%\' THEN \'plus_size\' WHEN LOWER(sku) LIKE \'4mlx%\' THEN \'luxe\' WHEN LOWER(sku) LIKE \'4mcr%\' THEN \'core\' WHEN LOWER(category) IN (\'perfumes\',\'accessories\',\'bags\',\'belts\',\'sunglasses\',\'shoes\',\'slip-ons\') THEN \'long_tail\' ELSE \'Snitch\' END AS l1_category, SUM(proj_qty) AS supply_qty FROM snitch_db.maplemonk.prod_demand_fob GROUP BY 1,2,3,4,5,6,7,8 ), supply_plan_conversion AS ( SELECT sku AS sku_group, CASE WHEN category = \'luxe_Shirts\' THEN \'Shirts\' WHEN category = \'luxe_Trousers\' THEN \'Trousers\' ELSE category END AS category, \'conversion\' as product_category, DATE_TRUNC(\'month\',TO_DATE(REPLACE(expected_delivery_date, \'-\', \'/\'),\'DD/MM/YYYY\')) AS month, fit, NULL AS collar, pattern AS print_design, CASE WHEN LOWER(sku) LIKE \'4mbg%\' THEN \'plus_size\' WHEN LOWER(sku) LIKE \'4mlx%\' THEN \'luxe\' WHEN LOWER(sku) LIKE \'4mcr%\' THEN \'core\' ELSE \'Snitch\' END AS l1_category, SUM(proj_qty) AS supply_qty FROM snitch_db.maplemonk.prod_demand_conversion WHERE category IS NOT NULL GROUP BY 1,2,3,4,5,6,7,8 ), supply_raw AS ( SELECT * FROM supply_plan_conversion_noos UNION ALL SELECT * FROM supply_plan_conversion_repeat UNION ALL SELECT * FROM supply_plan_fob UNION ALL SELECT * FROM supply_plan_conversion ), supply_plan AS ( SELECT month, l1_category, category, fit, collar, print_design, SUM(supply_qty) AS supply_qty FROM supply_raw GROUP BY 1,2,3,4,5,6 ), actual_pre as ( SELECT upper(trim(REVERSE(SUBSTRING(REVERSE(\"Item Type skuCode\"), CHARINDEX(\'-\', REVERSE(\"Item Type skuCode\")) + 1, LEN(\"Item Type skuCode\"))))) AS sku_group, DATE_TRUNC(\'MONTH\', \"PUTAWAY_UPDATED\"::date) AS PUTAWAY_UPDATED, sum(\"PUTAWAY_COMPLETED_QUANTITY\") AS PUTAWAY_COMPLETED_QUANTITY FROM snitch_db.maplemonk.putaway_tracking WHERE \"PUTAWAY_UPDATED\" >= TO_TIMESTAMP(\'2025-06-01T00:00:00.000000\') AND ((lower(FINAL_TYPE) = \'new inward\')) GROUP BY 1,2 ), actual_plan as ( select CASE WHEN LOWER(a.sku_group) LIKE \'4mbg%\' THEN \'plus_size\' WHEN LOWER(b.style) LIKE \'%luxe%\' THEN \'luxe\' WHEN LOWER(b.style) LIKE \'%core%\' THEN \'core\' WHEN LOWER(b.category) IN (\'perfumes\',\'accessories\',\'bags\',\'belts\',\'sunglasses\',\'shoes\',\'slip-ons\') THEN \'long_tail\' ELSE \'Snitch\' END AS l1_category, b.category AS category, b.fit, b.collar, b.print_design, a.PUTAWAY_UPDATED as month, sum(a.PUTAWAY_COMPLETED_QUANTITY) as actual_qty from actual_pre a left join snitch_db.maplemonk.metafields_data b on a.sku_group = b.sku_group group by 1,2,3,4,5,6 ), combined AS ( SELECT month, l1_category, category, fit, collar, print_design, demand_qty, 0 AS supply_qty, 0 AS actual_qty FROM demand_long UNION ALL SELECT month, l1_category, category, case when fit in (\'slouchy fit\',\'Flared Fit\',\'relax fit\') then \'Relaxed Fit\' else fit end as fit, case when collar = \'Classic\' then \'Spread\' when collar = \'Crew\' then \'Round\' when collar in (\'Button Down\',\'Mandarin\',\'V Neck\') then \'Others\' else collar end as collar, case when print_design in (\'Embroided/Self_Design\',\'Embroidered\') then \'Embroided\' when print_design in (\'Distressed\',\'Colourblocked\',\'Kurta\') then \'Others\' when print_design in (\'Clean Look\') then \'Plain\' when print_design in (\'Printed, Geometric\',\'Printed\',\'Graphic Print\',\'Abstract\',\'Printed, Graphic Print\',\'Printed, Abstract\',\'Printed, Floral\') then \'Printed\' when print_design = \'Plain\' then \'Solid\' when print_design = \'Stripes, Colourblocked\' then \'Stripes\' when print_design in (\'Textured, Self-Design\',\'Textured\',\'Self-Design, Textured\',\'Self-Design\') then \'Textured\' else print_design end as print_design, 0 AS demand_qty, sum(supply_qty) as supply_qty, 0 as actual_qty, FROM supply_plan group by 1,2,3,4,5,6 UNION ALL SELECT month, l1_category, category, case when fit in (\'Balloon Fit\',\'Slouchy Fit\') then \'Relaxed Fit\' else fit end as fit, case when collar in (\'Turtleneck\',\'Zip\') then \'High Neck\' when collar in (\'Mock\',\'V Neck\',\'Mandarin\',\'Button Down\',\'Half Zip\',\'Hooded\',\'Notch\',\'Lapel\',\'Shawl\',\'Button-Down\') then \'Others\' when collar = \'Crew\' then \'Round\' when collar in (\'Classic\',\'Cutaway\') then \'Spread\' else collar end as collar, case when print_design in (\'Square\',\'Checks, Geometric\',\'Plaid, Checked\',\'Checks, Floral, Abstract, Printed\',\'Gingham\', \'Checks, Printed\',\'Checks, Abstract\',\'Gingham, Checks\',\'Checks, Stripes\') then \'Checks\' when print_design in (\'Embroidered\',\'Geometric, Embroidered, Printed\',\'Embroidered, Graphic Print\',\'Self-Embroidered\') then \'Embroided\' when print_design = \'Geometric, Printed\' then \'Geometric\' when print_design in (\'Graphic Print\',\'Graphic Print, Printed\',\'Graphic Print, Embroidered\',\'Graphic Print, Colourblocked, Printed\',\'Colourblocked, Graphic Print\',\'Graphic Print, Embroidered, Printed\',\'Graphic Print,\', \'Graphic Print, Abstract, Printed\') then \'Graphic Printed\' when print_design in (\'Distressed\',\'Knitted\',\'Camouflage\',\'College Wear, Casual Wear\',\'Aviator\',\'Embellished\', \'Ombre\',\'Colorblocked\',\'Acid Washed\',\'Distressed Bootcut\') then \'Others\' when print_design = \'Clean Look\' then \'Plain\' when print_design in (\'Printed, Floral\',\'Floral, Printed\',\'Printed, Tie & Dye\',\'Printed, Graphic Print\', \'Printed, Geometric\',\'Abstract\',\'Floral\',\'Printed, Abstract\',\'Rectangular\',\'Geometric\',\'Abstract, Colourblocked, Printed\', \'Floral, Animal Print, Abstract, Printed\',\'Tie & Dye\',\'Printed, Animal Print\',\'Abstract, Printed\',\'Printed, Polka Dots\', \'Abstract, Floral, Printed\',\'Abstract, Marble, Printed\',\'Abstract, Embroidered\',\'Printed,Colourblocked\', \'Floral, Abstract, Printed\',\'Animal Print\',\'Oval\',\'Abstract, Tie & Dye, Printed\',\'Geometric, Checks, Printed\', \'Printed, Abstract, Printed\',\'Tye & Dye\') then \'Printed\' when print_design in (\'Stripes, Abstract, Printed\',\'Stripes, Printed\',\'Stripes, Colourblocked\',\'Self-Design, Stripes\', \'Stripes, Textured\') then \'Stripes\' when print_design in (\'Self-Design, Textured\', \'Textured, Self-Design\', \'Textured, Stripes\', \'Self-Design\', \'Self-Design, Tie & Dye\', \'Self-Design, Textured, Plain\', \'Self Design\', \'Self-Design, Geometric\', \'Sefl-Design\', \'Textured, Stripe\', \'Self-Deign\', \'Textured, Geometric\', \'Textured, Geometric, Self-Design\', \'Textured, Abstract\', \'Self-Design, Knitted\', \'Textured, Checks\') then \'Textured\' else print_design end as print_design, 0 AS demand_qty, 0 AS supply_qty, sum(actual_qty) as actual_qty FROM actual_plan group by 1,2,3,4,5,6 ) select l1_category, category, fit, collar, print_design, date_trunc(\'month\',month::date) as month, sum(demand_qty) as demand_qty, sum(supply_qty) as supply_qty, sum(actual_qty) as actual_qty from combined where l1_category not in (\'plus_size\',\'core\',\'luxe\') group by 1,2,3,4,5,6 union select l1_category, category, null as fit, null as collar, null as print_design, date_trunc(\'month\',month::date) as month, sum(demand_qty) as demand_qty, sum(supply_qty) as supply_qty, sum(actual_qty) as actual_qty from combined where l1_category in (\'plus_size\',\'core\',\'luxe\') group by 1,2,3,4,5,6 ); create or replace table snitch_db.maplemonk.demand_supply_actual_category_level as select category, l1_category, month, sum(case when category in (\'Shirts\',\'Jeans\',\'T-Shirts\') and l1_category = \'Snitch\' and demand_qty >0 and fit is not null then demand_qty when category in (\'Shirts\',\'Jeans\',\'T-Shirts\') and l1_category != \'Snitch\' and demand_qty >0 then demand_qty when category in (\'Blazers\',\'Boxers\',\'Cargo Pants\',\'Co-ords\',\'Hoodies\',\'Inner Wear\',\'Jackets\',\'Joggers & Trackpants\',\'Overshirt\',\'Pyjamas\',\'Shorts\',\'Sweaters\',\'Sweatshirts\',\'Trousers\',\'Accessories\',\'Bags\',\'Belts\',\'Perfumes\',\'Shoes\',\'Sunglasses\',\'Caps\',\'Socks\') then demand_qty end) as demand_qty, sum(supply_qty) as supply_qty, sum(actual_qty) as actual_qty from snitch_db.maplemonk.demand_supply_actual group by 1,2,3 ;",
